BOOL ReadStartupData(HANDLE pipe, STARTUP_DATA *sud) {
    DWORD bytesAvailable = 0;
    DWORD bytesRead = 0;
    DWORD totalBytes = 0;
    BOOL result = FALSE;

    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &bytesAvailable, NULL)) {
        LogError("Failed to peek into named pipe: %lu", GetLastError());
        return FALSE;
    }

    if (bytesAvailable == 0) {
        LogError("No data available in the named pipe.");
        return FALSE;
    }

    char *data = (char *)HeapAlloc(GetProcessHeap(), 1, bytesAvailable + 1);
    if (!data) {
        LogError("Memory allocation failed.");
        return FALSE;
    }

    if (!ReadFile(pipe, data, bytesAvailable, &bytesRead, NULL)) {
        LogError("Failed to read data from named pipe: %lu", GetLastError());
        goto cleanup;
    }

    if (bytesRead != bytesAvailable || data[bytesAvailable - 1] != '\0') {
        LogError("Malformed data in named pipe.");
        goto cleanup;
    }

    sud->data = data;
    sud->working_dir = _strdup(data);
    if (!sud->working_dir) {
        LogError("Failed to duplicate working directory string.");
        goto cleanup;
    }

    char *cmdLine = strchr(data, '\n');
    if (!cmdLine) {
        LogError("Command line options not found in data.");
        goto cleanup;
    }

    *cmdLine = '\0';
    cmdLine++;

    sud->command_line = _strdup(cmdLine);
    if (!sud->command_line) {
        LogError("Failed to duplicate command line string.");
        goto cleanup;
    }

    char *stdinData = strchr(cmdLine, '\n');
    if (!stdinData) {
        LogError("Standard input data not found in data.");
        goto cleanup;
    }

    *stdinData = '\0';
    sud->stdin_input = _strdup(stdinData + 1);
    if (!sud->stdin_input) {
        LogError("Failed to duplicate standard input string.");
        goto cleanup;
    }

    result = TRUE;

cleanup:
    if (!result) {
        if (sud->data) {
            HeapFree(GetProcessHeap(), 1, sud->data);
            sud->data = NULL;
        }
        if (sud->working_dir) {
            HeapFree(GetProcessHeap(), 1, sud->working_dir);
            sud->working_dir = NULL;
        }
        if (sud->command_line) {
            HeapFree(GetProcessHeap(), 1, sud->command_line);
            sud->command_line = NULL;
        }
        if (sud->stdin_input) {
            HeapFree(GetProcessHeap(), 1, sud->stdin_input);
            sud->stdin_input = NULL;
        }
    }

    return result;
}

BOOL ReadStartupDataFromPipe(HANDLE pipe, STARTUP_DATA *sud) {
    DWORD dwRead = 0;
    DWORD dwAvail = 0;
    DWORD dwMsgSize = 0;
    BOOL bResult = FALSE;
    LPBYTE pBuffer = NULL;

    // Check if data is available in the pipe
    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &dwAvail, &dwMsgSize)) {
        LogError("Failed to peek into the pipe");
        return FALSE;
    }

    if (dwAvail == 0) {
        LogError("No data available in the pipe");
        return FALSE;
    }

    // Allocate memory to read the data
    pBuffer = (LPBYTE)HeapAlloc(GPTR, dwAvail);
    if (pBuffer == NULL) {
        LogError("Failed to allocate memory for reading pipe data");
        return FALSE;
    }

    // Read the data from the pipe
    if (!ReadFile(pipe, pBuffer, dwAvail, &dwRead, NULL) || dwRead != dwAvail) {
        LogError("Failed to read data from the pipe");
        HeapFree(pBuffer);
        return FALSE;
    }

    // Ensure the data is NULL-terminated
    if (pBuffer[dwRead - 1] != '\0') {
        LogError("Received data is not NULL-terminated");
        HeapFree(pBuffer);
        return FALSE;
    }

    // Parse the data into STARTUP_DATA structure
    sud->workingDirectory = (LPWSTR)pBuffer;
    sud->commandLine = (LPWSTR)(pBuffer + wcslen(sud->workingDirectory) + sizeof(WCHAR));
    sud->standardInput = (LPWSTR)(sud->commandLine + wcslen(sud->commandLine) + sizeof(WCHAR));

    // Verify that the data pointers are valid and within the allocated buffer
    if ((DWORD)((BYTE*)sud->standardInput + wcslen(sud->standardInput) * sizeof(WCHAR)) > dwRead) {
        LogError("Malformed data in the pipe");
        HeapFree(pBuffer);
        return FALSE;
    }

    bResult = TRUE;
    return bResult;
}

#include <windows.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LOG_ERROR(fmt, ...) fprintf(stderr, "Error: " fmt "\n", __VA_ARGS__)

BOOL ReadStartupData(HANDLE pipe, STARTUP_DATA *sud) {
    DWORD dwRead = 0;
    DWORD dwAvail = 0;
    DWORD dwMsgSize = 0;
    char *buffer = NULL;
    char *data = NULL;

    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &dwAvail, &dwMsgSize)) {
        LOG_ERROR("Failed to peek named pipe: %lu", GetLastError());
        return FALSE;
    }

    if (dwAvail == 0 || dwMsgSize == 0) {
        LOG_ERROR("No data available in the pipe.");
        return FALSE;
    }

    if (dwAvail != dwMsgSize) {
        LOG_ERROR("Malformed data in pipe. Expected message size %lu, but %lu bytes available.", dwMsgSize, dwAvail);
        return FALSE;
    }

    buffer = (char *)malloc(dwAvail);
    if (buffer == NULL) {
        LOG_ERROR("Failed to allocate memory for pipe data.");
        return FALSE;
    }

    if (!ReadFile(pipe, buffer, dwAvail, &dwRead, NULL)) {
        LOG_ERROR("Failed to read from pipe: %lu", GetLastError());
        free(buffer);
        return FALSE;
    }

    if (dwRead != dwAvail) {
        LOG_ERROR("Read incomplete data. Expected %lu bytes, read %lu bytes.", dwAvail, dwRead);
        free(buffer);
        return FALSE;
    }

    if (buffer[dwRead - 1] != '\0') {
        LOG_ERROR("Data is not null-terminated.");
        free(buffer);
        return FALSE;
    }

    data = buffer;

    sud->working_directory = data;
    data += strlen(data) + 1;

    sud->command_line = data;
    data += strlen(data) + 1;

    sud->stdin_input = data;

    return TRUE;
}

BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA *sud) {
    DWORD dwBytesAvailable = 0;
    DWORD dwBytesRead = 0;
    LPVOID lpBuffer = NULL;
    PCHAR pData = NULL;
    PCHAR pWorkingDir = NULL;
    PCHAR pCommandLine = NULL;
    PCHAR pStdIn = NULL;
    BOOL bResult = FALSE;

    // Check number of bytes available in the pipe
    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &dwBytesAvailable, NULL) || dwBytesAvailable == 0) {
        LogError("No data available in the named pipe.");
        return FALSE;
    }

    // Allocate memory to read data
    lpBuffer = GlobalAlloc(GMEM_FIXED, dwBytesAvailable + 1);
    if (!lpBuffer) {
        LogError("Failed to allocate memory for reading data.");
        return FALSE;
    }

    // Read data from the pipe
    if (!ReadFile(pipe, lpBuffer, dwBytesAvailable, &dwBytesRead, NULL) || dwBytesRead != dwBytesAvailable) {
        LogError("Failed to read data from the named pipe.");
        goto Cleanup;
    }

    pData = (PCHAR)lpBuffer;

    // Check if data is NULL-terminated
    if (pData[dwBytesAvailable - 1] != '\0') {
        LogError("Data is not NULL-terminated.");
        goto Cleanup;
    }

    // Parse the data
    pWorkingDir = pData;
    pData = pWorkingDir + strlen(pWorkingDir) + 1;
    pCommandLine = pData;
    pData = pCommandLine + strlen(pCommandLine) + 1;
    pStdIn = pData;

    // Populate the STARTUP_DATA structure
    sud->working_directory = pWorkingDir;
    sud->command_line = pCommandLine;
    sud->standard_input = pStdIn;

    bResult = TRUE;

Cleanup:
    if (!bResult && lpBuffer) {
        GlobalFree(lpBuffer);
    }

    return bResult;
}

#include <windows.h>

BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA *sud) {
    DWORD bytesAvailable = 0;
    DWORD bytesRead = 0;
    BOOL result = FALSE;
    DWORD error = ERROR_SUCCESS;

    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &bytesAvailable, NULL) || bytesAvailable == 0) {
        error = GetLastError();
        SetLastError(error);
        return FALSE;
    }

    LPBYTE buffer = (LPBYTE)HeapAlloc(GetProcessHeap(), GMEM_FIXED, bytesAvailable);
    if (!buffer) {
        error = ERROR_NOT_ENOUGH_MEMORY;
        SetLastError(error);
        return FALSE;
    }

    if (!ReadFile(pipe, buffer, bytesAvailable, &bytesRead, NULL) || bytesRead != bytesAvailable) {
        error = GetLastError();
        HeapFree(GetProcessHeap(), GMEM_FIXED, buffer);
        SetLastError(error);
        return FALSE;
    }

    if (buffer[bytesRead - 1] != '\0') {
        error = ERROR_INVALID_DATA;
        HeapFree(GetProcessHeap(), GMEM_FIXED, buffer);
        SetLastError(error);
        return FALSE;
    }

    sud->workingDirectory = (LPSTR)HeapAlloc(GetProcessHeap(), GMEM_FIXED, MAX_PATH);
    sud->commandLine = (LPSTR)HeapAlloc(GetProcessHeap(), GMEM_FIXED, MAX_PATH);
    sud->stdInput = (LPSTR)HeapAlloc(GetProcessHeap(), GMEM_FIXED, MAX_PATH);

    if (!sud->workingDirectory || !sud->commandLine || !sud->stdInput) {
        error = ERROR_NOT_ENOUGH_MEMORY;
        HeapFree(GetProcessHeap(), GMEM_FIXED, buffer);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->workingDirectory);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->commandLine);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->stdInput);
        SetLastError(error);
        return FALSE;
    }

    LPSTR data = (LPSTR)buffer;
    LPSTR token = strtok(data, "|");
    if (!token) {
        error = ERROR_INVALID_DATA;
        HeapFree(GetProcessHeap(), GMEM_FIXED, buffer);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->workingDirectory);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->commandLine);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->stdInput);
        SetLastError(error);
        return FALSE;
    }
    lstrcpyA(sud->workingDirectory, token);

    token = strtok(NULL, "|");
    if (!token) {
        error = ERROR_INVALID_DATA;
        HeapFree(GetProcessHeap(), GMEM_FIXED, buffer);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->workingDirectory);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->commandLine);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->stdInput);
        SetLastError(error);
        return FALSE;
    }
    lstrcpyA(sud->commandLine, token);

    token = strtok(NULL, "|");
    if (!token) {
        error = ERROR_INVALID_DATA;
        HeapFree(GetProcessHeap(), GMEM_FIXED, buffer);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->workingDirectory);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->commandLine);
        HeapFree(GetProcessHeap(), GMEM_FIXED, sud->stdInput);
        SetLastError(error);
        return FALSE;
    }
    lstrcpyA(sud->stdInput, token);

    HeapFree(GetProcessHeap(), GMEM_FIXED, buffer);
    return TRUE;
}
